// Resolve a collision between the ball and a single brick: flip the velocity
// component along the least-penetrated axis (both on a corner), and push the
// ball out of the brick so it cannot re-collide next frame.
export function bounceOffBrick(ball, brick) {
  const overlapX = Math.min(
    ball.x + ball.r - brick.x,
    brick.x + brick.w - (ball.x - ball.r)
  );
  const overlapY = Math.min(
    ball.y + ball.r - brick.y,
    brick.y + brick.h - (ball.y - ball.r)
  );

  if (overlapX < overlapY) {
    // side hit
    ball.vx = ball.x < brick.x + brick.w / 2 ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    // push out horizontally
    if (ball.x < brick.x + brick.w / 2) {
      ball.x = brick.x - ball.r;
    } else {
      ball.x = brick.x + brick.w + ball.r;
    }
