export function brickCollide(state) {
  // swept detection from previous position to current
  const { ball } = state;
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;
  const dx = ball.x - px;
  const dy = ball.y - py;
  const dist = Math.hypot(dx, dy);
  const segments = Math.max(1, Math.ceil(dist / BRICK_H));

  let bounced = false;
  let destroyed = 0;

  for (let i = 1; i <= segments && !bounced; i++) {
    const t = i / segments;
    const sx = px + dx * t;
    const sy = py + dy * t;
    const sample = { x: sx, y: sy, r: ball.r };

    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      if (!collides(sample, brick)) continue;
      // The ball touches this brick at this point: destroy & score it.
      brick.alive = false;
      destroyed += 1;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      if (!bounced) {
        // Bounce once per pass: place the ball at the point of first
        // contact and push it out of the brick.
        ball.x = sx;
        ball.y = sy;
        bounceOffBrick(ball, brick);
        bounced = true;
      }
    }
  }
  return destroyed;
}
