```js
// --- Brick collision (pure, testable) --------------------------------------

// Resolves the ball hitting one brick: flips the velocity component along the
// axis of least penetration (both on a corner hit) and pushes the ball back
// out of the brick, so it cannot re-collide on the next frame (sticky bounce).
export function bounceOffBrick(ball, brick) {
  const overlapX = Math.min(
    ball.x + ball.r - brick.x,
    brick.x + brick.w - (ball.x - ball.r)
  );
  const overlapY = Math.min(
    ball.y + ball.r - brick.y,
    brick.y + brick.h - (ball.y - ball.r)
  );

  if (overlapX < overlapY) {
    // Side hit: flip vx, leave vy untouched.
    ball.vx = -ball.vx;
    ball.x = ball.vx < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
  } else if (overlapY < overlapX) {
    // Top/bottom hit: flip vy, leave vx untouched.
    ball.vy = -ball.vy;
    ball.y = ball.vy < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  } else {
    // Corner hit: equal penetration on both axes, flip both.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = ball.vx < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = ball.vy < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
  return ball;
}
```

