```js
// Swept brick collision + bounce. The ball can jump further than a brick is
// thick in one step (tunnelling), so the path from the ball's previous to its
// current position is sampled: the first contact point is where the bounce
// happens. Applies the bounce exactly once even when the ball overlaps two
// neighbouring bricks at a seam (a second flip would cancel the first and let
// the ball through). Destroys every brick touched at the contact point.
// Returns the number of bricks destroyed.
export function brickCollide(state) {
  const { ball } = state;
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;
  const dx = ball.x - px;
  const dy = ball.y - py;
  const distance = Math.hypot(dx, dy);
  const segments = Math.max(1, Math.ceil(distance / BRICK_H));

  let destroyed = 0;
  let bounced = false;

  for (let i = 1; i <= segments && !bounced; i++) {
    const t = i / segments;
    const sample = { x: px + dx * t, y: py + dy * t, r: ball.r };

    for (const brick of state.bricks) {
      if (!brick.alive || !collides(sample, brick)) continue;

      // Every brick touched at this point is destroyed & scored.
      brick.alive = false;
      destroyed += 1;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      // The bounce applies exactly once: at the first contact point.
      if (!bounced) {
        ball.x = sample.x;
        ball.y = sample.y;
        bounceOffBrick(ball, brick);
        bounced = true;
      }
    }
  }

  return destroyed;
}
```

