```js
export function brickCollide(state) {
  const { ball } = state;
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;
  const dx = ball.x - px;
  const dy = ball.y - py;
  const distance = Math.hypot(dx, dy);
  const segments = Math.max(1, Math.ceil(distance / BRICK_H));

  let destroyed = 0;
  let bounced = false;

  for (let i = 1; i <= segments && !bounced; i++) {
    const t = i / segments;
    const sample = { x: px + dx * t, y: py + dy * t, r: ball.r };

    // All bricks the ball touches at this point: destroy & score them, and
    // resolve the bounce against their combined footprint (a seam overlaps
    // two bricks at once; bouncing off one of them alone would let the ball
    // fall through the middle of the row/column).
    const touched = state.bricks.filter((b) => b.alive && collides(sample, b));
    if (touched.length === 0) continue;

    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const brick of touched) {
      brick.alive = false;
      destroyed += 1;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      minX = Math.min(minX, brick.x);
      minY = Math.min(minY, brick.y);
      maxX = Math.max(maxX, brick.x + brick.w);
      maxY = Math.max(maxY, brick.y + brick.h);
    }

    ball.x = sample.x;
    ball.y = sample.y;
    bounceOffBrick(ball, { x: minX, y: minY, w: maxX - minX, h: maxY - minY });
    bounced = true;
  }

  return destroyed;
}
