```js
// --- Brick collision (pure, testable) --------------------------------------

// Resolves the ball hitting a brick (or a seam of bricks merged into one
// rectangle): flips the velocity component along the axis of least
// penetration — `vy` on a top/bottom hit, `vx` on a side hit, both on a
// corner — then pushes the ball back out of the rectangle, so it cannot
// re-collide and re-flip on the next frame (sticky bounce). Mutates and
// returns the ball.
export function bounceOffBrick(ball, brick) {
  const overlapX = Math.min(
    ball.x + ball.r - brick.x,
    brick.x + brick.w - (ball.x - ball.r)
  );
  const overlapY = Math.min(
    ball.y + ball.r - brick.y,
    brick.y + brick.h - (ball.y - ball.r)
  );

  if (overlapX < overlapY) {
    // Side hit: flip vx, leave vy untouched.
    ball.vx = -ball.vx;
    ball.x = ball.vx < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
  } else if (overlapY < overlapX) {
    // Top/bottom hit: flip vy, leave vx untouched.
    ball.vy = -ball.vy;
    ball.y = ball.vy < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  } else {
    // Corner hit: equal penetration on both axes, flip both.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = ball.vx < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = ball.vy < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
  return ball;
}

// Swept brick collision. The ball can travel further than a brick is thick in
// a single step (at level 6+ a capped frame moves it 35.5 px against the 34 px
// needed to cross a brick), so the path from the ball's previous position to
// its current one is sampled: the first contact point is where the bounce
// happens. At a seam the ball overlaps two bricks in the same pass — they are
// destroyed and scored together, and the bounce is applied exactly once
// against their combined footprint (a second flip would cancel the first and
// let the ball through). Destroys bricks and scores; returns how many were
// destroyed.
export function brickCollide(state) {
  const { ball } = state;
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;
  const dx = ball.x - px;
  const dy = ball.y - py;
  const distance = Math.hypot(dx, dy);
  // Sample spacing below BRICK_H guarantees at least one sample inside the
  // overlap window (brick thickness + ball diameter) even at max speed.
  const segments = Math.max(1, Math.ceil(distance / BRICK_H));

  let destroyed = 0;
  let bounced = false;

  for (let i = 1; i <= segments && !bounced; i++) {
    const t = i / segments;
    const sample = { x: px + dx * t, y: py + dy * t, r: ball.r };

    // Every brick touched at this point is destroyed and scored.
    const touched = state.bricks.filter((brick) => brick.alive && collides(sample, brick));
    if (touched.length === 0) continue;

    // Merge the touched bricks into one rectangle: bouncing off a single one
    // at a seam would flip the wrong axis (the ball is wider than the 8 px gap
    // and would fall through the middle of a row).
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    for (const brick of touched) {
      brick.alive = false;
      destroyed += 1;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      minX = Math.min(minX, brick.x);
      minY = Math.min(minY, brick.y);
      maxX = Math.max(maxX, brick.x + brick.w);
      maxY = Math.max(maxY, brick.y + brick.h);
    }

    // Place the ball at the point of first contact, then push it out.
    ball.x = sample.x;
    ball.y = sample.y;
    bounceOffBrick(ball, { x: minX, y: minY, w: maxX - minX, h: maxY - minY });
    bounced = true;
  }

  return destroyed;
}
