// --- #1: brick bounce (see ISSUES.md) --------------------------------------

test('bounceOffBrick: top hit flips vy only and pushes the ball out', () => {
  const brick = { x: 100, y: 100, w: 40, h: 20 };
  const ball = { x: 120, y: 99, r: 8, vx: 30, vy: 200 };
  bounceOffBrick(ball, brick);
  assert.equal(ball.vy, -200, 'vy should flip upward');
  assert.equal(ball.vx, 30, 'vx must be left untouched');
  assert.equal(ball.y + ball.r, brick.y, 'ball pushed out above the brick');
  assert.equal(collides(ball, brick), false, 'ball must not overlap the brick anymore');
});

test('bounceOffBrick: bottom hit flips vy only and pushes the ball out', () => {
  const brick = { x: 100, y: 100, w: 40, h: 20 };
  const ball = { x: 120, y: 121, r: 8, vx: 30, vy: -200 };
  bounceOffBrick(ball, brick);
  assert.equal(ball.vy, 200, 'vy should flip downward');
  assert.equal(ball.vx, 30, 'vx must be left untouched');
  assert.equal(ball.y - ball.r, brick.y + brick.h, 'ball pushed out below the brick');
  assert.equal(collides(ball, brick), false, 'ball must not overlap the brick anymore');
});

test('bounceOffBrick: left-face hit flips vx only and pushes the ball out', () => {
  const brick = { x: 100, y: 100, w: 40, h: 20 };
  const ball = { x: 99, y: 110, r: 8, vx: 200, vy: 30 };
  bounceOffBrick(ball, brick);
  assert.equal(ball.vx, -200, 'vx should flip leftward');
  assert.equal(ball.vy, 30, 'vy must be left untouched');
  assert.equal(ball.x + ball.r, brick.x, 'ball pushed out left of the brick');
  assert.equal(collides(ball, brick), false, 'ball must not overlap the brick anymore');
});

test('bounceOffBrick: right-face hit flips vx only and pushes the ball out', () => {
  const brick = { x: 100, y: 100, w: 40, h: 20 };
  const ball = { x: 141, y: 110, r: 8, vx: -200, vy: 30 };
  bounceOffBrick(ball, brick);
  assert.equal(ball.vx, 200, 'vx should flip rightward');
  assert.equal(ball.vy, 30, 'vy must be left untouched');
  assert.equal(ball.x - ball.r, brick.x + brick.w, 'ball pushed out right of the brick');
  assert.equal(collides(ball, brick), false, 'ball must not overlap the brick anymore');
});

test('bounceOffBrick: corner hit flips both components', () => {
  const brick = { x: 100, y: 100, w: 40, h: 20 };
  // Ball inside the top-right corner with equal penetration on both axes.
  const ball = { x: 136, y: 104, r: 8, vx: 200, vy: 200 };
  bounceOffBrick(ball, brick);
  assert.equal(ball.vx, -200, 'vx should flip');
  assert.equal(ball.vy, -200, 'vy should flip');
  assert.equal(collides(ball, brick), false, 'ball pushed out diagonally');
});

test('brickCollide: direct hit destroys the brick and bounces the ball', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  const x = brick.x + brick.w / 2;
  const py = brick.y - BALL_R - 2;
  state.ball = { x, y: py + 10, px: x, py, r: BALL_R, vx: 0, vy: 400 };
  const destroyed = brickCollide(state);
  assert.equal(destroyed, 1);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy < 0, 'ball should bounce upward');
  assert.ok(state.ball.y + state.ball.r <= brick.y, 'ball pushed out above the brick');
  assert.ok(state.score > 0, 'breaking a brick scores points');
  assert.ok(
    !state.bricks.some((b) => b.alive && collides(state.ball, b)),
    'ball must not overlap any remaining brick'
  );
});

test('brickCollide: seam between two side-by-side bricks bounces exactly once', () => {
  const state = createState(1);
  const a = state.bricks[0];
  const b = state.bricks[1];
  const x = a.x + a.w + BRICK_GAP / 2; // middle of the gap between the two bricks
  const py = a.y - BALL_R - 2;
  state.ball = { x, y: py + 12, px: x, py, r: BALL_R, vx: 0, vy: 400 };
  const destroyed = brickCollide(state);
  assert.equal(destroyed, 2, 'both seam bricks are destroyed');
  assert.equal(a.alive, false);
  assert.equal(b.alive, false);
  assert.ok(state.ball.vy < 0, 'vy flipped exactly once (bounce must not cancel)');
});

test('brickCollide: seam between two stacked bricks bounces exactly once', () => {
  const state = createState(1);
  const top = state.bricks[0];
  const bottom = state.bricks[BRICK_COLS]; // same column, next row
  const y = top.y + top.h + BRICK_GAP / 2; // middle of the row gap
  const x = 8; // just right of the left wall, overlapping both left faces
  state.ball = { x, y, px: x - 2, py: y, r: BALL_R, vx: 500, vy: 0 };
  const destroyed = brickCollide(state);
  assert.equal(destroyed, 2, 'both seam bricks are destroyed');
  assert.equal(top.alive, false);
  assert.equal(bottom.alive, false);
  assert.ok(state.ball.vx < 0, 'vx flipped exactly once (bounce must not cancel)');
});

test('brickCollide: swept detection catches a ball that jumps over a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  const x = brick.x + brick.w / 2;
  // One step takes the ball from above the brick to below it: neither
  // endpoint overlaps the brick, only the swept path does.
  state.ball = {
    x,
    y: brick.y + brick.h + BALL_R + 2, // below the brick
    px: x,
    py: brick.y - BALL_R - 2, // above the brick
    r: BALL_R,
    vx: 0,
    vy: 500,
  };
  const destroyed = brickCollide(state);
  assert.equal(destroyed, 1, 'tunnelled brick is still detected');
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy < 0, 'ball bounces upward after tunnelling');
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

