edits.newText:
// --- Brick collision (pure, testable) --------------------------------------

// Resolves the ball hitting a brick (or a seam of bricks merged into one
// rectangle): flips the velocity component along the axis of least
// penetration — `vy` on a top/bottom hit, `vx` on a side hit, both on a
// corner — and leaves the other component untouched. The ball is then pushed
// back out of the rectangle, otherwise it still overlaps on the next frame
// and re-flips forever (sticky bounce). Mutates and returns the ball.
export function bounceOffBrick(ball, brick) {
  const overlapX = Math.min(
    ball.x + ball.r - brick.x,
    brick.x + brick.w - (ball.x - ball.r)
  );
  const overlapY = Math.min(
    ball.y + ball.r - brick.y,
    brick.y + brick.h - (ball.y - ball.r)
  );

  if (overlapX < overlapY) {
    // Side hit: flip vx, leave vy exactly as it was.
    ball.vx = -ball.vx;
    ball.x = ball.vx < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
  } else if (overlapY < overlapX) {
    // Top/bottom hit: flip vy, leave vx exactly as it was.
    ball.vy = -ball.vy;
    ball.y = ball.vy < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  } else {
    // Corner hit: equal penetration means a diagonal hit, flip both.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = ball.vx < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = ball.vy < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
  return ball;
}

// Swept brick collision. The ball can travel further than a brick is thick in
// one step (at level 6+ a capped frame moves it 35.5 px against the 34 px
// needed to cross a brick), so the path from the ball's previous position to
// its current one is sampled and the bounce happens at the first contact
// point. At a seam the ball (14 px across) overlaps two bricks (8 px gap) in
// the same pass: every touched brick is destroyed and scored together, and the
// bounce is applied exactly once against their combined footprint — applied
// twice, `-v` would cancel out and the ball would go straight through.
// Returns the number of bricks destroyed.
export function brickCollide(state) {
  const { ball } = state;
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;
  const dx = ball.x - px;
  const dy = ball.y - py;
  const distance = Math.hypot(dx, dy);
  // Sample spacing below BRICK_H guarantees at least one sample inside the
  // overlap window (brick thickness + ball diameter) at any speed.
  const segments = Math.max(1, Math.ceil(distance / BRICK_H));

  let destroyed = 0;
  let bounced = false;

  for (let i = 1; i <= segments && !bounced; i++) {
    const t = i / segments;
    const sample = { x: px + dx * t, y: py + dy * t, r: ball.r };

    // Every brick touched at this point is destroyed and scored.
    const touched = state.bricks.filter((brick) => brick.alive && collides(sample, brick));
    if (touched.length === 0) continue;

    // Merge the touched bricks into one rectangle: bouncing off a single one
    // at a seam would flip the wrong axis and let the ball fall through the
    // middle of a row/column.
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    for (const brick of touched) {
      brick.alive = false;
      destroyed += 1;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      minX = Math.min(minX, brick.x);
      minY = Math.min(minY, brick.y);
      maxX = Math.max(maxX, brick.x + brick.w);
      maxY = Math.max(maxY, brick.y + brick.h);
    }

    // Place the ball at the point of first contact, then push it out.
    ball.x = sample.x;
    ball.y = sample.y;
    bounceOffBrick(ball, { x: minX, y: minY, w: maxX - minX, h: maxY - minY });
    bounced = true;
  }

  return destroyed;
}

// --- Rendering (DOM) -------------------------------------------------------

// Main render loop: applies the brick collisions (pure logic) then draws.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Brick collision: swept detection, one bounce per pass, scoring — all in
  // brickCollide(). frame() only draws.
  brickCollide(state);

  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

